SELECT shd.hiddenDangerNum, shd.market_tenant, mc.market_name FROM market_config mc INNER JOIN ( select count(id) as hiddenDangerNum, market_tenant, market_name from safety_hidden_danger
and tenant = #{query.marketTenant}
and create_time >= #{query.period.begin} and create_time < #{query.period.end}
group by market_tenant order by hiddenDangerNum asc ) shd ON mc.market_tenant = shd.market_tenant where mc.status = true

SELECT mc.market_tenant tenantID, mc.market_name tenantName, c.hidden_danger_status status, c.count count FROM market_config mc LEFT JOIN ( SELECT shd.market_tenant, shd.hidden_danger_status, COUNT(1) count FROM safety_hidden_danger shd
AND shd.market_tenant IN
#{id}
AND shd.create_time BETWEEN #{createdPeriod.begin} AND #{createdPeriod.end}
GROUP BY shd.hidden_danger_status ) c ON c.market_tenant = mc.market_tenant
mc.status = true
AND mc.market_tenant IN
#{id}

SELECT shd.hidden_danger_status groupKey, COUNT(shd.id) count FROM safety_hidden_danger shd left join market_config mc on mc.market_tenant = shd.market_tenant
mc.status = true
AND shd.market_tenant IN
#{id}
AND shd.create_time BETWEEN #{query.createdPeriod.begin} AND #{query.createdPeriod.end}
GROUP BY shd.hidden_danger_status

